import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import api from "../api/axios";

export default function RestaurantMenu() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [restaurant, setRestaurant] = useState(null);
  const [menu, setMenu] = useState([]);
  const [cart, setCart] = useState({}); // menuItemId -> quantity
  const [address, setAddress] = useState("");
  const [placing, setPlacing] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    api.get(`/restaurants/${id}`).then(({ data }) => {
      setRestaurant(data.restaurant);
      setMenu(data.menu);
    });
  }, [id]);

  const changeQty = (itemId, delta) => {
    setCart((prev) => {
      const next = { ...prev, [itemId]: Math.max(0, (prev[itemId] || 0) + delta) };
      if (next[itemId] === 0) delete next[itemId];
      return next;
    });
  };

  const total = menu.reduce((sum, item) => sum + (cart[item._id] || 0) * item.price, 0);
  const itemCount = Object.values(cart).reduce((a, b) => a + b, 0);

  const placeOrder = async () => {
    setError("");
    if (!address.trim()) {
      setError("Add a delivery address first");
      return;
    }
    setPlacing(true);
    try {
      const items = Object.entries(cart).map(([menuItem, quantity]) => ({ menuItem, quantity }));
      const { data } = await api.post("/orders", {
        restaurantId: id,
        items,
        deliveryAddress: { text: address },
      });
      navigate(`/orders/${data._id}`);
    } catch (err) {
      setError(err.response?.data?.message || "Could not place order");
    } finally {
      setPlacing(false);
    }
  };

  if (!restaurant) return <div className="page">Loading menu…</div>;

  return (
    <div className="page">
      <div className="eyebrow">{restaurant.cuisine || "Menu"}</div>
      <h1>{restaurant.name}</h1>
      <hr className="route-rule" style={{ margin: "20px 0 28px" }} />

      <div style={{ display: "grid", gridTemplateColumns: "1fr 320px", gap: 28 }}>
        <div className="grid" style={{ gridTemplateColumns: "1fr", gap: 12 }}>
          {menu.map((item) => (
            <div key={item._id} className="card" style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <h3 style={{ fontSize: 16 }}>{item.name}</h3>
                <p style={{ color: "var(--paper-dim)", fontSize: 13, margin: "4px 0" }}>{item.description}</p>
                <span style={{ fontFamily: "var(--font-mono)", color: "var(--signal-dim)" }}>₹{item.price}</span>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <button className="btn btn-ghost btn-sm" onClick={() => changeQty(item._id, -1)}>−</button>
                <span>{cart[item._id] || 0}</span>
                <button className="btn btn-ghost btn-sm" onClick={() => changeQty(item._id, 1)}>+</button>
              </div>
            </div>
          ))}
        </div>

        <div className="card" style={{ alignSelf: "start", position: "sticky", top: 20 }}>
          <h3>Your order</h3>
          <hr className="route-rule" style={{ margin: "14px 0" }} />
          {itemCount === 0 && <p style={{ color: "var(--paper-dim)", fontSize: 14 }}>Cart is empty</p>}
          {itemCount > 0 && (
            <p style={{ fontFamily: "var(--font-mono)", fontSize: 22, margin: "10px 0" }}>₹{total}</p>
          )}
          <div className="field">
            <label>Delivery address</label>
            <textarea rows={3} value={address} onChange={(e) => setAddress(e.target.value)} placeholder="Flat, street, city" />
          </div>
          {error && <div className="error-text">{error}</div>}
          <button className="btn btn-primary btn-block" disabled={itemCount === 0 || placing} onClick={placeOrder}>
            {placing ? "Placing order…" : `Place order · ₹${total}`}
          </button>
        </div>
      </div>
    </div>
  );
}
